import React, { useRef, useState, useEffect } from "react";
import styled from "styled-components";
import { apiCreateSample } from "../service/sample";
import { apiGetVirulenceInfo } from "../service/virulence";
import { apiGetAmrInfo } from "../service/amr";
import { apiGetExperimentsByUserId } from "../service/experiment";
import { useDispatch, useSelector } from "react-redux";
import { useNotice } from "../context/NoticeContext";
import ResultPopup from "../components/ResultPopup";
import LoadingSpinner from "../components/LoadingSpinner";
import { useTranslation } from "react-i18next"; // 👈 Thêm dòng này


const Submit = () => {
  const { t } = useTranslation(); // 👈 Hook i18n
  const { userId } = useSelector((state) => state.user);
  const { showNotice } = useNotice();

  const [selectedExperiment, setSelectedExperiment] = useState("");
  const [header, setHeader] = useState("");
  const [length, setLength] = useState(0);
  const [fastaFilePath, setFastaFilePath] = useState("");
  const [sampleName, setSampleName] = useState("");
  const [file, setFile] = useState(null);
  const fileInputRef = useRef(null);
  const [fastaInfo, setFastaInfo] = useState({});
  const [virulenceInfo, setVirulenceInfo] = useState([]);
  const [amrInfo, setAmrInfo] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [experiments, setExperiments] = useState([]);

  const closeModal = () => setShowModal(false);

  useEffect(() => {
    const fetchExperiments = async () => {
      if (!userId) return;
      try {
        const res = await apiGetExperimentsByUserId(userId);
        setExperiments(res.data);
      } catch (err) {
        console.log("Lỗi", err);
      }
    };
    fetchExperiments();
  }, [userId]);

  const handleFileChange = (e) => {
    const uploadedFile = e.target.files[0];
    if (uploadedFile) {
      setFile(uploadedFile);
      setFastaFilePath(uploadedFile.name);

      const reader = new FileReader();
      reader.onload = function (event) {
        const text = event.target.result;
        const lines = text.split(/\r?\n/);
        const headerLine = lines.find((line) => line.startsWith(">"));
        setHeader(headerLine || "");
        const sequenceLines = lines.filter((line) => !line.startsWith(">") && line.trim() !== "");
        const totalLength = sequenceLines.join("").length;
        setLength(totalLength);
      };
      reader.readAsText(uploadedFile);
    }
  };

  const [errors, setErrors] = useState({
    selectedExperiment: "",
    sampleName: "",
    file: "",
  });

  const validateForm = () => {
    const newErrors = {
      selectedExperiment: "",
      sampleName: "",
      file: "",
    };
    let isValid = true;

    if (!selectedExperiment) {
      newErrors.selectedExperiment = t("submit.error.selectExperiment");
      isValid = false;
    }

    if (!sampleName.trim()) {
      newErrors.sampleName = t("submit.error.sampleName");
      isValid = false;
    }

    if (!file) {
      newErrors.file = t("submit.error.file");
      isValid = false;
    }

    setErrors(newErrors);
    return isValid;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validateForm()) return;
    setIsLoading(true);
    try {
      const result = await apiCreateSample(userId, selectedExperiment, sampleName, header, length, fastaFilePath);
      const sampleId = result.data._id;
      setFastaInfo(result.data);
      const [virulenceRes, amrRes] = await Promise.all([
        apiGetVirulenceInfo(file, sampleId),
        apiGetAmrInfo(file, sampleId),
      ]);
      setVirulenceInfo(virulenceRes.data);
      setAmrInfo(amrRes.data);
      showNotice(1, t("submit.success"));
      setShowModal(true);
    } catch (error) {
      showNotice(0, t("submit.fail"));
    } finally {
      setIsLoading(false);
    }
  };

  const handleReset = () => {
    setSelectedExperiment("");
    setSampleName("");
    setFile(null);
    setFastaFilePath("");
    setHeader("");
    setLength(0);
    setErrors({
      selectedExperiment: "",
      sampleName: "",
      file: "",
    });
  };

  return (
    <Container>
      <Wrapper>
        <Title>{t("submit.title")}</Title>
        <DropdownWrapper>
          <Dropdown value={selectedExperiment} onChange={(e) => setSelectedExperiment(e.target.value)}>
            <option value="">{t("submit.selectExperiment")}</option>
            {experiments.map((experiment) => (
              <option key={experiment._id} value={experiment._id}>
                {experiment.name}
              </option>
            ))}
          </Dropdown>
          {errors.selectedExperiment && <ErrorText>{errors.selectedExperiment}</ErrorText>}
          <InputWrapper>
            <Input
              type="text"
              value={sampleName}
              onChange={(e) => setSampleName(e.target.value)}
              placeholder={t("submit.sampleNamePlaceholder")}
            />
            {errors.sampleName && <ErrorText>{errors.sampleName}</ErrorText>}
            <ChooseFileButtonWrapper>
              <ChooseFileButton>
                <UploadIcon />
                {t("submit.chooseFile")}
                <input type="file" accept=".fa,.fas,.fna,.fasta" onChange={handleFileChange} ref={fileInputRef} />
              </ChooseFileButton>
              {file && <FileName>{file.name}</FileName>}
            </ChooseFileButtonWrapper>
            {errors.file && <ErrorText>{errors.file}</ErrorText>}
          </InputWrapper>
        </DropdownWrapper>
        <ButtonWrapper>
          <ButtonSubmit type="button" onClick={handleSubmit}>
            {t("submit.submitBtn")}
          </ButtonSubmit>
          <ButtonReset type="button" onClick={handleReset}>
            {t("submit.resetBtn")}
          </ButtonReset>
        </ButtonWrapper>
        {isLoading && <LoadingSpinner />}
        <ResultPopup
          fastaInfo={fastaInfo}
          virulenceInfo={virulenceInfo}
          amrInfo={amrInfo}
          showModal={showModal}
          closeModal={closeModal}
        />
      </Wrapper>
    </Container>
  );
};

export default Submit;
